{"action":"python","code":"import xarray as xr, numpy as np, json
b=xr.open_zarr('/inputs/baseline.zarr',chunks=None)['sst']
t=xr.open_zarr('/inputs/target.zarr',chunks=None)['sst']
clim=b.mean('time')
a=t-clim
def box(a,lo0,lo1,la0,la1):
    s=a.sel(longitude=slice(lo0,lo1),latitude=slice(la0,la1))
    w=np.cos(np.deg2rad(s.latitude))
    return s.weighted(w).mean(('latitude','longitude'))
w=box(a,50,70,-10,10); e=box(a,90,110,-10,0)
ans={'dates':[str(d)[:10] for d in t.time.values],'west_c':[float(x) for x in w.values],'east_c':[float(x) for x in e.values],'dmi_c':[float(x) for x in (w-e).values],'units':'degree_Celsius'}
json.dump(ans,open('/work/answer.json','w'));print(ans)"}

{"action":"python","code":"import xarray as xr, numpy as np, pandas as pd, json
ds=xr.open_zarr('/inputs/irregular.zarr',chunks=None)
print(ds); print(ds.time_bounds.values); print(ds.precip.values)
tb=ds.time_bounds.values
if not np.issubdtype(tb.dtype,np.datetime64):
    tb=pd.to_datetime(tb.ravel()).values.reshape(tb.shape)
weeks=[(np.datetime64('2024-01-01'),np.datetime64('2024-01-08')),(np.datetime64('2024-01-08'),np.datetime64('2024-01-15'))]
tot=[]
for ws,we in weeks:
    s=0.0
    for (a,b),r in zip(tb,ds.precip.values):
        lo=max(a,ws); hi=min(b,we)
        if hi>lo:
            s+=float(r)*((hi-lo)/np.timedelta64(1,'D'))
    tot.append(s)
ans={'dates':['2024-01-01','2024-01-08'],'totals_mm':tot,'units':'mm'}
print(ans)
json.dump(ans,open('/work/answer.json','w'))"}

